// ---- config -----------------------------------------------------------
var markers = [
    { name: 'Nashville',    lat: 36.1627, lon: -86.7816 },
    { name: 'Knoxville',    lat: 35.9606, lon: -83.9207 },
    { name: 'Memphis',      lat: 35.1495, lon: -90.0490 },
    { name: 'Chattanooga',  lat: 35.0456, lon: -85.3097 }
];

var cotType = 'b-m-p-s-m';
var channelName = 'NWS';
var staleMinutes = 6;
// -------------------------------------------------------------------------

function esc(s) {
    return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function kpToGScale(kp) {
    if (kp >= 9) return 5;
    if (kp >= 8) return 4;
    if (kp >= 7) return 3;
    if (kp >= 6) return 2;
    if (kp >= 5) return 1;
    return 0;
}

var GSCALE_COLOR = {
    0: -16711936, 1: -256, 2: -23296, 3: -23296, 4: -65536, 5: -65536
};

var kpData = flow.get('swpcKp');
var alertsData = flow.get('swpcAlerts');

var latestKp = null;
if (Array.isArray(kpData) && kpData.length) {
    var lastRow = kpData[kpData.length - 1];
    latestKp = parseFloat(lastRow.Kp);
}

var gScale = (latestKp !== null && !isNaN(latestKp)) ? kpToGScale(latestKp) : 0;
var colorValue = GSCALE_COLOR[gScale];

var remarksParts = ['Space Weather Status'];
remarksParts.push(latestKp !== null ? ('Kp index: ' + latestKp + ' (G' + gScale + (gScale ? '' : ' - quiet') + ')') : 'Kp index: unavailable');

if (Array.isArray(alertsData) && alertsData.length) {
    var recent = alertsData.slice(-3).reverse();
    recent.forEach(function (a) {
        var msgText = a.message || a.Message || '';
        var lines = String(msgText).split('\n');

        var codeLine = lines.find(function (l) { return l.indexOf('Space Weather Message Code:') !== -1; });
        var code = codeLine ? codeLine.replace('Space Weather Message Code:', '').trim() : (a.product_id || 'UNKNOWN');

        var descLine = lines.find(function (l) {
            return /^(WARNING|WATCH|ALERT|SUMMARY|EXTENDED WARNING|CONTINUED ALERT|CANCEL)/.test(l.trim());
        });
        var desc = descLine ? descLine.trim() : 'No description available';

        remarksParts.push(code + ': ' + desc);
    });
}

var remarks = esc(remarksParts.join(' | '));

var now = new Date();
var start = now.toISOString();
var stale = new Date(now.getTime() + staleMinutes * 60000).toISOString();

var msgs = markers.map(function (m) {
    var uid = 'swpc-space-weather-status-' + m.name.toLowerCase();
    var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
        '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" ' +
        'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
        '<point lat="' + m.lat + '" lon="' + m.lon + '" hae="0" ce="9999999.0" le="9999999.0"/>' +
        '<detail>' +
        '<contact callsign="Space Weather (' + esc(m.name) + ')"/>' +
        '<color value="' + colorValue + '"/>' +
        '<remarks>' + remarks + '</remarks>' +
        '<marti><dest name="' + esc(channelName) + '"/></marti>' +
        '</detail>' +
        '</event>';
    return { payload: cot };
});

return [msgs];
